<?php declare(strict_types=1); namespace App\Controllers; use App\Core\Controller; use App\Core\Session; use App\Services\LiquidityPoolService; final class LiquidityApiController extends Controller{private LiquidityPoolService $s; public function __construct(){$this->s=new LiquidityPoolService();} private function j($d){header('Content-Type: application/json');echo json_encode($d); } public function getSession(string $id):void{$this->j($this->s->getProjectorState((int)$id)['session']);} public function getTeamState():void{$this->j($this->s->getProjectorState((int)Session::get('liquidity_session_id',0)));} public function getRanking(string $id):void{$this->j($this->s->getRanking((int)$id));} public function getFeed(string $id):void{$this->j((new \App\Repositories\LiquidityEventRepository())->getRecentBySession((int)$id,50));} public function getPoolState(string $id):void{$this->j((new \App\Repositories\LiquidityPoolRepository())->findBySessionId((int)$id));} public function getProjectorState(string $id):void{$this->j($this->s->getProjectorState((int)$id));}}
